UPDATE inventory_warehouse_stock
SET stock_available=stock_available+#{available},stock_reserved=stock_reserved+#{reserved},
    stock_sold=stock_sold+#{sold}
WHERE product_id=#{productId} AND warehouse_id=#{warehouseId}
  AND stock_available+#{available}>=0 AND stock_reserved+#{reserved}>=0 AND stock_sold+#{sold}>=0
